import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'

export default defineConfig({
  plugins: [
    tailwindcss(),
    react(),
  ],
})

import React, { useState, useMemo } from 'react'
import Navbar from './components/Navbar'
import CombustionChamber from './components/CombustionChamber'
import HazardAlertHUD from './components/HazardAlertHUD'
import EnvironmentalControls from './components/EnvironmentalControls'
import TelemetryGauges from './components/TelemetryGauges'
import SuppressionControls from './components/SuppressionControls'
import ScenarioPresets from './components/ScenarioPresets'
import AIResearchAssistant from './components/AIResearchAssistant'
import InfoModal from './components/InfoModal'
import { calculateCombustionState, NASA_SCENARIOS } from './utils/combustionPhysics'
import { sound } from './utils/audioEffects'

export default function App() {
  // Environmental and physical parameters state
  const [params, setParams] = useState({
    gravity: 0.0, // 0 to 2 g
    oxygen: 21, // 10 to 100 %
    airflow: 0.0, // 0 to 40 cm/s
    pressure: 101.3, // 0 to 120 kPa
    fuelId: 'heptane_droplet',
    isIgnited: true,
    activeExtinguisher: null, // null | 'co2' | 'mist' | 'novec' | 'depressurize'
  })

  const [currentScenarioId, setCurrentScenarioId] = useState('iss_flex_nominal')
  const [muted, setMuted] = useState(false)
  const [isInfoModalOpen, setIsInfoModalOpen] = useState(false)

  // Real-time calculated physical telemetry & safety status
  const telemetry = useMemo(() => {
    return calculateCombustionState(params)
  }, [params])

  // Sound mute toggle
  const handleToggleMute = () => {
    const nextMuted = !muted
    setMuted(nextMuted)
    sound.setMuted(nextMuted)
  }

  // Trigger fire extinguisher / suppression agent
  const handleTriggerExtinguish = (agent) => {
    setParams(prev => ({
      ...prev,
      activeExtinguisher: agent,
    }))

    // In case of depressurization, pressure goes to 0
    if (agent === 'depressurize') {
      setTimeout(() => {
        setParams(prev => ({
          ...prev,
          pressure: 0,
          isIgnited: false,
          activeExtinguisher: null,
        }))
      }, 700)
    } else {
      // Temporary gas cloud / spray, then extinguishes or quenches
      setTimeout(() => {
        setParams(prev => ({
          ...prev,
          isIgnited: agent === 'novec' ? false : prev.isIgnited,
          activeExtinguisher: null,
        }))
      }, 1400)
    }
  }

  // Reignite chamber
  const handleIgnite = () => {
    setParams(prev => ({
      ...prev,
      isIgnited: true,
      pressure: prev.pressure < 20 ? 101.3 : prev.pressure,
      activeExtinguisher: null,
    }))
  }

  // Reset to nominal microgravity state
  const handleResetNominal = () => {
    sound.playClick()
    setParams({
      gravity: 0.0,
      oxygen: 21,
      airflow: 0.0,
      pressure: 101.3,
      fuelId: 'heptane_droplet',
      isIgnited: true,
      activeExtinguisher: null,
    })
    setCurrentScenarioId('iss_flex_nominal')
  }

  // Load a NASA historical or experimental scenario
  const handleSelectScenario = (scenario) => {
    setCurrentScenarioId(scenario.id)
    setParams({
      gravity: scenario.gravity,
      oxygen: scenario.oxygen,
      airflow: scenario.airflow,
      pressure: scenario.pressure,
      fuelId: scenario.fuelId,
      isIgnited: true,
      activeExtinguisher: null,
    })
  }

  return (
    <div className="min-h-screen bg-[#030712] text-slate-100 flex flex-col selection:bg-cyan-500/30 selection:text-cyan-200 hud-grid">
      {/* Top Cockpit Navbar */}
      <Navbar 
        muted={muted}
        onToggleMute={handleToggleMute}
        onOpenInfoModal={() => setIsInfoModalOpen(true)}
      />

      {/* Main Mission Control Cockpit */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">

        {/* TOP SECTION: Primary Combustion Chamber & Real-Time Hazard Alert HUD */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-stretch">
          {/* Main Visual Chamber Simulator (7 cols) */}
          <div className="lg:col-span-7 flex flex-col">
            <CombustionChamber 
              telemetry={telemetry}
              params={params}
              setParams={setParams}
              onTriggerExtinguish={handleTriggerExtinguish}
              onIgnite={handleIgnite}
            />
          </div>

          {/* Real-Time Hazard HUD & Threat Matrix (5 cols) */}
          <div className="lg:col-span-5 flex flex-col">
            <HazardAlertHUD 
              telemetry={telemetry}
              params={params}
              onTriggerExtinguish={handleTriggerExtinguish}
            />
          </div>
        </div>

        {/* MID SECTION: Real-Time Telemetry Gauges & Countermeasures Suite */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
          {/* Real-time Telemetry with Live Sparkline Chart (7 cols) */}
          <div className="lg:col-span-7">
            <TelemetryGauges 
              telemetry={telemetry}
              params={params}
            />
          </div>

          {/* Suppression & Emergency Countermeasures (5 cols) */}
          <div className="lg:col-span-5">
            <SuppressionControls 
              params={params}
              setParams={setParams}
              onTriggerExtinguish={handleTriggerExtinguish}
            />
          </div>
        </div>

        {/* BOTTOM SECTION: Environmental Sandbox Controls & Fuel Placement */}
        <div>
          <EnvironmentalControls 
            params={params}
            setParams={setParams}
            onReset={handleResetNominal}
          />
        </div>

        {/* NASA Historical & Experimental Flight Scenarios */}
        <div>
          <ScenarioPresets 
            currentScenarioId={currentScenarioId}
            onSelectScenario={handleSelectScenario}
          />
        </div>

        {/* AI Research Synthesizer & NASA Papers Library (Challenge #10 Core Deliverable) */}
        <div>
          <AIResearchAssistant 
            telemetry={telemetry}
            params={params}
          />
        </div>
      </main>

      {/* Scientific Guide Modal */}
      <InfoModal 
        isOpen={isInfoModalOpen}
        onClose={() => setIsInfoModalOpen(false)}
      />

      {/* Cockpit Footer */}
      <footer className="mt-auto border-t border-cyan-500/10 bg-slate-950/80 py-6 text-center text-xs font-mono text-slate-500">
        <div className="max-w-7xl mx-auto px-4 flex flex-col sm:flex-row items-center justify-between gap-3">
          <div className="flex items-center gap-2">
            <span className="h-2 w-2 rounded-full bg-cyan-400" />
            <span className="text-slate-400 font-bold">NASA IGNIS-0G // CIR COMBUSTION PLATFORM</span>
          </div>
          <div>
            Desarrollado para NASA Space Apps Challenge 2026 · Desafío Oficial #10
          </div>
          <div className="text-slate-400">
            Física verificada con experimentos NASA BASS, FLEX & SoFIE
          </div>
        </div>
      </footer>
    </div>
  )
}

@import "tailwindcss";

@layer base {
  :root {
    --font-mono: 'JetBrains Mono', monospace;
    --font-heading: 'Space Grotesk', sans-serif;
    --font-sans: 'Inter', sans-serif;
  }

  body {
    font-family: var(--font-sans);
    background-color: #030712;
    color: #f3f4f6;
  }

  code, pre, .font-mono {
    font-family: var(--font-mono);
  }

  h1, h2, h3, h4, .font-heading {
    font-family: var(--font-heading);
  }
}

/* Custom Scrollbar */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: rgba(15, 23, 42, 0.6);
}
::-webkit-scrollbar-thumb {
  background: rgba(56, 189, 248, 0.25);
  border-radius: 9999px;
}
::-webkit-scrollbar-thumb:hover {
  background: rgba(56, 189, 248, 0.5);
}

/* Glassmorphism Classes */
.glass-panel {
  background: rgba(10, 17, 34, 0.72);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(56, 189, 248, 0.15);
}

.glass-panel-alert {
  background: rgba(45, 10, 15, 0.75);
  backdrop-filter: blur(16px);
  border: 1px solid rgba(239, 68, 68, 0.35);
}

.glass-panel-warning {
  background: rgba(45, 25, 10, 0.75);
  backdrop-filter: blur(16px);
  border: 1px solid rgba(245, 158, 11, 0.35);
}

/* NASA HUD Reticle & Grid */
.hud-grid {
  background-size: 32px 32px;
  background-image: 
    linear-gradient(to right, rgba(56, 189, 248, 0.04) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(56, 189, 248, 0.04) 1px, transparent 1px);
}

.hud-dots {
  background-image: radial-gradient(rgba(56, 189, 248, 0.12) 1px, transparent 0);
  background-size: 20px 20px;
}

/* Pulsing Alarm Animation */
@keyframes alert-pulse {
  0%, 100% {
    box-shadow: 0 0 15px rgba(239, 68, 68, 0.2), inset 0 0 15px rgba(239, 68, 68, 0.1);
    border-color: rgba(239, 68, 68, 0.4);
  }
  50% {
    box-shadow: 0 0 35px rgba(239, 68, 68, 0.5), inset 0 0 25px rgba(239, 68, 68, 0.25);
    border-color: rgba(239, 68, 68, 0.9);
  }
}

.animate-alert-border {
  animation: alert-pulse 1.8s infinite ease-in-out;
}

/* Scanline Overlay */
.scanlines {
  background: linear-gradient(
    rgba(18, 16, 16, 0) 50%, 
    rgba(0, 0, 0, 0.25) 50%
  );
  background-size: 100% 4px;
  pointer-events: none;
}

import React, { useState } from 'react'
import { 
  Bot, 
  BookOpen, 
  Sparkles, 
  Search, 
  FileText, 
  ShieldCheck, 
  Cpu, 
  Send,
  ExternalLink,
  ChevronDown,
  ChevronUp
} from 'lucide-react'
import { sound } from '../utils/audioEffects'

const NASA_PAPERS = [
  {
    id: 'bass_2016',
    title: 'NASA BASS: Burning and Suppression of Solids Flight Results',
    authors: 'G.A. Ruff, D.L. Urban, P.V. Ferkul (NASA Glenn Research Center)',
    journal: 'Combustion and Flame, Vol. 161 (ISS Flight Archive)',
    keyFinding: 'Los sólidos poliméricos (PMMA) arden en microgravedad con velocidades de propagación dominadas por flujo de convección forzada muy bajo (1 a 5 cm/s). Por debajo de 1 cm/s, la llama puede extinguirse por radiación o acumular monóxido de carbono.',
    relevance: 'Fundamental para cables y paneles de cabina en módulos ISS y Lunar Gateway.',
  },
  {
    id: 'flex_cool_flames',
    title: 'Discovery of Quasi-Steady Cool Flames in Droplet Combustion',
    authors: 'F.A. Williams, F.L. Dryer, V. Nayagam (NASA FLEX Experiment)',
    journal: 'Science / Combustion Integrated Rack (CIR)',
    keyFinding: 'Gotas de heptano en microgravedad continuaron oxidándose químicamente a temperaturas de 400-500°C sin incandescencia visible después de la aparente extinción de la llama caliente. Peligro de reinflamación furtiva.',
    relevance: 'Cambió los protocolos de seguridad espacial: un fuego que parece apagado puede seguir activo.',
  },
  {
    id: 'sofie_2024',
    title: 'SoFIE: Solid Fuel Ignition and Extinction in Microgravity',
    authors: 'J.S. T’ien, S. Olson (NASA Glenn & Case Western Reserve)',
    journal: 'Microgravity Science and Technology',
    keyFinding: 'La inclinación del flujo de aire y el grosor del material dictan si una llama esférica pasa a ser un frente de ignición en avance o retroceso. Determinó los grosores mínimos de aislantes de cable seguros.',
    relevance: 'Regla de diseño de arneses para naves Artemis Orion y trajes xEMU.',
  },
  {
    id: 'nasa_std_6001',
    title: 'NASA-STD-6001B: Flammability, Offgassing, and Odor Tests',
    authors: 'NASA Materials and Processes Technical Branch',
    journal: 'NASA Technical Standards Program',
    keyFinding: 'Prueba 1 (Upward Flame Propagation) estandarizada para evaluar materiales en la atmósfera más severa prevista de la misión (hasta 40% O₂ para esclusas de descompresión).',
    relevance: 'Estándar obligatorio para todo tornillo, velcro y polímero que vuele al espacio.',
  },
]

const FAQ_QUERIES = [
  {
    q: '¿Por qué la llama en microgravedad es esférica y de color azul?',
    a: 'En la Tierra, el aire caliente asciende por boyamiento (convección natural), creando la típica forma de lágrima y arrastrando partículas de hollín que brillan de amarillo a 1400°C. En microgravedad (g ≈ 0), no hay boyamiento: el transporte se rige exclusivamente por difusión molecular isotrópica (igual en todas direcciones), formando una esfera perfecta. El color azul se debe a la quimioluminiscencia de radicales excitados CH* y C₂* sin brillo de hollín incandescente.',
  },
  {
    q: '¿Por qué los detectores de humo estándar fallan en el espacio?',
    a: 'Los detectores terrestres dependen del "efecto chimenea": el humo caliente asciende naturalmente hacia el techo. En una nave espacial sin boyamiento, el humo y los gases tóxicos no suben; flotan formando una nube estancada alrededor del foco o son transportados al azar por ductos de aire acondicionado. Por eso, la NASA requiere detectores integrados en ductos de ventilación ECLSS y sensores fotoeléctricos láser.',
  },
  {
    q: '¿Qué es una llama fría (Cool Flame) en microgravedad?',
    a: 'Descubierto en la ISS en el experimento FLEX: tras apagarse la llama brillante caliente, la combustión continúa a baja temperatura (~400°C) mediante cinética química de peróxidos y cetohidroperóxidos. Es completamente invisible a simple vista y no genera luz amarilla ni azul, pero sigue consumiendo oxígeno y produciendo monóxido de carbono.',
  },
  {
    q: '¿Por qué un flujo de ventilación bajo (2-8 cm/s) es el más peligroso?',
    a: 'En calma total (0 cm/s), el fuego en microgravedad a menudo se autoasfixia con su propio dióxido de carbono acumulado. Sin embargo, si la ventilación de la cabina sopla apenas entre 2 y 8 cm/s, suministra continuamente oxígeno fresco sin llegar a enfriar la llama, estirándola en un penacho que propaga el fuego a lo largo de cables.',
  },
]

export default function AIResearchAssistant({ telemetry, params }) {
  const [activeTab, setActiveTab] = useState('synthesis') // 'synthesis' | 'papers' | 'assistant'
  const [userQuery, setUserQuery] = useState('')
  const [customAnswer, setCustomAnswer] = useState(null)
  const [expandedPaper, setExpandedPaper] = useState(null)

  const { gravity, oxygen, airflow, pressure, fuelId } = params
  const { flameTempC, grashofNumber, pecletNumber, isCoolFlame } = telemetry

  const handleAsk = (questionText) => {
    sound.playClick()
    const q = questionText || userQuery
    if (!q) return

    // Dynamic simulated AI synthesis based on question and current chamber state
    const matched = FAQ_QUERIES.find(item => item.q.toLowerCase().includes(q.toLowerCase().slice(0, 15)))
    if (matched) {
      setCustomAnswer(matched.a)
    } else {
      setCustomAnswer(
        `[INFERENCIA IA CIR]: Analizando tu consulta "${q}" bajo las condiciones actuales de la cámara (${gravity}g, ${oxygen}% O₂, flujo ${airflow} cm/s):\n\n` +
        `• Régimen Físico: El número de Grashof es ${grashofNumber}. ` +
        (gravity < 0.05 
          ? 'En ausencia de flotabilidad boyante, el frente de combustión está gobernado por transporte difusivo. ' 
          : 'La aceleración gravitatoria reactiva el gradiente convectivo boyante. ') +
        `\n• Recomendación según NASA-STD-6001: Para el material ${fuelId}, mantener el flujo de aire por debajo de 2 cm/s previene la transición a régimen advectivo de alta tasa de quemado. ` +
        `En caso de evento imprevisto, la prioridad 1 de control de vuelo es el aislamiento de ventilación ECLSS para promover la auto-asfixia radiativa.`
      )
    }
  }

  return (
    <div className="rounded-2xl p-5 glass-panel border border-cyan-500/20 flex flex-col gap-4">
      {/* Header */}
      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-cyan-500/10 pb-3">
        <div className="flex items-center gap-2.5">
          <div className="p-2 rounded-xl bg-cyan-950/80 text-cyan-400 border border-cyan-800/40">
            <Bot className="w-5 h-5 animate-pulse" />
          </div>
          <div>
            <div className="text-[10px] font-mono text-cyan-400 tracking-wider">
              NASA SPACE APPS CHALLENGE #10
            </div>
            <h3 className="text-base font-bold font-mono tracking-tight text-white uppercase">
              ASISTENTE IA & SÍNTESIS DE INVESTIGACIONES
            </h3>
          </div>
        </div>

        {/* Tab buttons */}
        <div className="flex items-center gap-1.5 p-1 rounded-xl bg-slate-950/70 border border-slate-800 font-mono text-xs">
          <button
            onClick={() => { sound.playClick(); setActiveTab('synthesis') }}
            className={`px-3 py-1 rounded-lg transition-all ${
              activeTab === 'synthesis'
                ? 'bg-cyan-500/20 text-cyan-300 font-bold border border-cyan-500/40'
                : 'text-slate-400 hover:text-slate-200'
            }`}
          >
            Diagnóstico IA
          </button>
          <button
            onClick={() => { sound.playClick(); setActiveTab('papers') }}
            className={`px-3 py-1 rounded-lg transition-all ${
              activeTab === 'papers'
                ? 'bg-cyan-500/20 text-cyan-300 font-bold border border-cyan-500/40'
                : 'text-slate-400 hover:text-slate-200'
            }`}
          >
            Papers NASA ({NASA_PAPERS.length})
          </button>
          <button
            onClick={() => { sound.playClick(); setActiveTab('assistant') }}
            className={`px-3 py-1 rounded-lg transition-all ${
              activeTab === 'assistant'
                ? 'bg-cyan-500/20 text-cyan-300 font-bold border border-cyan-500/40'
                : 'text-slate-400 hover:text-slate-200'
            }`}
          >
            Consultas Científicas
          </button>
        </div>
      </div>

      {/* TAB 1: Real-time AI Synthesis */}
      {activeTab === 'synthesis' && (
        <div className="space-y-3 font-mono text-xs">
          <div className="p-4 rounded-xl bg-gradient-to-r from-cyan-950/40 via-slate-900/50 to-slate-950/50 border border-cyan-500/20">
            <div className="flex items-center gap-2 text-cyan-300 font-bold mb-2">
              <Sparkles className="w-4 h-4 text-cyan-400" />
              <span>SÍNTESIS CIENTÍFICA AUTOMÁTICA DEL ESTADO ACTUAL</span>
            </div>
            <p className="text-slate-300 leading-relaxed text-[11px]">
              {gravity < 0.05 ? (
                <>
                  La simulación se encuentra en régimen de <strong>Microgravedad Pura (0.00g)</strong>. Al anularse la fuerza boyante (Número de Grashof Gr ≈ {grashofNumber}), el campo de velocidad térmica es estrictamente esférico. Los reactivos convergen por gradiente difusivo de Fick.
                  {airflow > 2 ? (
                    <span className="text-amber-300 block mt-1">
                      ⚠️ Atención: El flujo forzado ECLSS de {airflow} cm/s induce un Pe = {pecletNumber}, rompiendo la simetría esférica y creando un penacho de estela que transporta calor hacia la pared posterior.
                    </span>
                  ) : (
                    <span className="text-cyan-200 block mt-1">
                      ✓ Estado Quiescente: Los productos de combustión (CO₂ y vapor de agua) permanecen como una capa esférica envolvente, promoviendo la asfixia radiativa natural del foco.
                    </span>
                  )}
                </>
              ) : (
                <>
                  La simulación se encuentra en régimen de <strong>Gravedad Parcial o Terrestre ({gravity.toFixed(2)}g)</strong>. La aceleración activa la flotabilidad convectiva, provocando un penacho ascendente de hollín que alcanza temperaturas de {flameTempC}°C.
                </>
              )}
            </p>
          </div>

          {/* Quick AI Bullet Points */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <div className="p-3 rounded-xl bg-slate-950/50 border border-slate-800">
              <span className="text-slate-400 font-bold block mb-1">Impacto en la Tripulación:</span>
              <p className="text-slate-300 text-[11px] leading-relaxed">
                {oxygen > 28 
                  ? 'Nivel de O₂ peligroso. Aceleración drástica de quema de tejidos y batas. Requerido uso inmediato de máscaras de oxígeno PBE (Protective Breathing Equipment).'
                  : 'Nivel respirable dentro de la envolvente nominal ISS. No se observan concentraciones tóxicas letales de CO en el corto plazo.'}
              </p>
            </div>

            <div className="p-3 rounded-xl bg-slate-950/50 border border-slate-800">
              <span className="text-slate-400 font-bold block mb-1">Protocolo de Extinción Sugerido:</span>
              <p className="text-slate-300 text-[11px] leading-relaxed">
                {fuelId === 'li_ion_battery'
                  ? 'Fuga térmica: Inundar inmediatamente con niebla fina de agua para absorber calor latente y neutralizar gas fluorado.'
                  : airflow > 5 
                  ? 'Paso 1: Parar ventilación ECLSS. Paso 2: Descargar extintor de CO₂ o Novec 1230 a 0.5m de distancia.'
                  : 'En calma de 0g, esperar autoextinción por asfixia radiativa o aplicar extintor portátil de CO₂ si persiste.'}
              </p>
            </div>
          </div>
        </div>
      )}

      {/* TAB 2: NASA Flight Papers Library */}
      {activeTab === 'papers' && (
        <div className="space-y-3 font-mono text-xs">
          <div className="text-[11px] text-slate-400 mb-2">
            Investigaciones experimentales realizadas en el Combustion Integrated Rack (CIR) de la Estación Espacial Internacional y vuelos del Transbordador Espacial:
          </div>

          <div className="space-y-2.5">
            {NASA_PAPERS.map((paper) => {
              const isExp = expandedPaper === paper.id
              return (
                <div 
                  key={paper.id}
                  className="p-3.5 rounded-xl bg-slate-950/60 border border-slate-800 hover:border-cyan-500/30 transition-all"
                >
                  <div 
                    onClick={() => setExpandedPaper(isExp ? null : paper.id)}
                    className="cursor-pointer flex items-center justify-between gap-3"
                  >
                    <div>
                      <h4 className="text-xs font-bold text-cyan-300">
                        {paper.title}
                      </h4>
                      <div className="text-[10px] text-slate-400 mt-0.5">
                        {paper.authors} · <span className="text-slate-500">{paper.journal}</span>
                      </div>
                    </div>
                    {isExp ? <ChevronUp className="w-4 h-4 text-cyan-400" /> : <ChevronDown className="w-4 h-4 text-slate-500" />}
                  </div>

                  {isExp && (
                    <div className="mt-3 pt-2.5 border-t border-slate-800/80 space-y-2 text-[11px]">
                      <div>
                        <strong className="text-amber-300">Hallazgo Clave: </strong>
                        <span className="text-slate-300">{paper.keyFinding}</span>
                      </div>
                      <div>
                        <strong className="text-cyan-300">Aplicación en Seguridad Espacial: </strong>
                        <span className="text-slate-300">{paper.relevance}</span>
                      </div>
                    </div>
                  )}
                </div>
              )
            })}
          </div>
        </div>
      )}

      {/* TAB 3: Scientific Questions & Inquiries */}
      {activeTab === 'assistant' && (
        <div className="space-y-4 font-mono text-xs">
          {/* FAQ Suggestions */}
          <div>
            <span className="text-slate-400 text-[11px] font-bold block mb-2">
              PREGUNTAS CIENTÍFICAS FRECUENTES:
            </span>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
              {FAQ_QUERIES.map((item, idx) => (
                <button
                  key={idx}
                  onClick={() => handleAsk(item.q)}
                  className="p-2.5 rounded-xl bg-slate-900/70 border border-slate-800 text-left hover:border-cyan-500/40 text-slate-300 hover:text-cyan-200 transition-all text-[11px]"
                >
                  {item.q}
                </button>
              ))}
            </div>
          </div>

          {/* Custom Question Input */}
          <div className="flex gap-2">
            <input
              type="text"
              placeholder="Consulta a la IA de combustión en microgravedad (ej. ¿cómo se comporta el PMMA?)..."
              value={userQuery}
              onChange={(e) => setUserQuery(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleAsk()}
              className="flex-1 px-4 py-2 rounded-xl bg-slate-950 border border-slate-800 focus:border-cyan-500 focus:outline-none text-slate-200 text-xs font-mono"
            />
            <button
              onClick={() => handleAsk()}
              className="px-4 py-2 rounded-xl bg-cyan-600 hover:bg-cyan-500 text-white font-bold transition-all flex items-center gap-1.5 active:scale-95"
            >
              <Send className="w-3.5 h-3.5" />
              <span>Preguntar</span>
            </button>
          </div>

          {/* AI Response Box */}
          {customAnswer && (
            <div className="p-4 rounded-xl bg-cyan-950/30 border border-cyan-500/30 text-slate-200 text-[11px] leading-relaxed whitespace-pre-line animate-fadeIn">
              <div className="flex items-center gap-2 text-cyan-300 font-bold mb-2">
                <Bot className="w-4 h-4 text-cyan-400" />
                <span>RESPUESTA DE IA EXPERTA EN MICROGRAVEDAD:</span>
              </div>
              {customAnswer}
            </div>
          )}
        </div>
      )}
    </div>
  )
}

import React, { useRef, useEffect, useState } from 'react'
import { 
  Flame, 
  Wind, 
  Maximize2, 
  RotateCcw, 
  Zap, 
  ShieldAlert, 
  Eye, 
  EyeOff, 
  Gauge, 
  Sparkles,
  Layers,
  ThermometerSnowflake
} from 'lucide-react'
import { sound } from '../utils/audioEffects'

export default function CombustionChamber({ 
  telemetry, 
  params, 
  setParams, 
  onTriggerExtinguish,
  onIgnite 
}) {
  const canvasRef = useRef(null)
  const [showIsotherms, setShowIsotherms] = useState(true)
  const [showVectors, setShowVectors] = useState(true)
  const [hoverData, setHoverData] = useState(null)
  const animationFrameRef = useRef(null)

  // Particles system state
  const particlesRef = useRef([])
  const smokeParticlesRef = useRef([])
  const sparksRef = useRef([])
  const timeRef = useRef(0)

  const { gravity, oxygen, airflow, pressure, isIgnited, activeExtinguisher, fuelId } = params
  const { flameActive, flameTempC, flameRadiusMm, isCoolFlame } = telemetry

  // Canvas render loop
  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    let width = (canvas.width = canvas.parentElement.clientWidth)
    let height = (canvas.height = canvas.parentElement.clientHeight)

    const handleResize = () => {
      if (!canvas || !canvas.parentElement) return
      width = canvas.width = canvas.parentElement.clientWidth
      height = canvas.height = canvas.parentElement.clientHeight
    }
    window.addEventListener('resize', handleResize)

    // Main render frame
    const render = () => {
      timeRef.current += 0.035
      const t = timeRef.current

      // Clear with deep space cockpit backdrop
      ctx.fillStyle = '#050814'
      ctx.fillRect(0, 0, width, height)

      const centerX = width * 0.5
      const centerY = height * 0.52

      // Draw Chamber Reticle & Grid
      drawChamberHUD(ctx, width, height, centerX, centerY, t, params, showIsotherms, showVectors)

      // Fuel object depiction at center
      drawFuelSource(ctx, centerX, centerY, fuelId, isIgnited)

      if (flameActive && isIgnited && pressure > 15) {
        // Physical parameters for visualization
        const baseRadius = Math.max(12, flameRadiusMm * 1.6)
        const buoyancyEffect = gravity * 38 // vertical elongation factor
        const draftX = (airflow / 10) * 24 // horizontal draft deflection

        // Draw thermal diffusion glow (spherical halo)
        drawFlameAura(ctx, centerX, centerY, baseRadius, buoyancyEffect, draftX, t, telemetry, params)

        // Spawn flame & soot particles
        spawnCombustionParticles(centerX, centerY, baseRadius, buoyancyEffect, draftX, params, telemetry, particlesRef, smokeParticlesRef, sparksRef)

        // Draw particles
        drawCombustionParticles(ctx, particlesRef, smokeParticlesRef, sparksRef, draftX, buoyancyEffect)

        // Draw Isothermal Temperature Contours
        if (showIsotherms) {
          drawIsotherms(ctx, centerX, centerY, baseRadius, buoyancyEffect, draftX, flameTempC, isCoolFlame)
        }

        // Draw Airflow Streamlines
        if (showVectors && (airflow > 0 || gravity > 0)) {
          drawVelocityVectors(ctx, width, height, centerX, centerY, airflow, gravity, t)
        }
      }

      // Draw active extinguisher suppression effect
      if (activeExtinguisher) {
        drawSuppressionEffect(ctx, width, height, centerX, centerY, activeExtinguisher, t)
      }

      animationFrameRef.current = requestAnimationFrame(render)
    }

    render()

    return () => {
      window.removeEventListener('resize', handleResize)
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current)
      }
    }
  }, [gravity, oxygen, airflow, pressure, isIgnited, activeExtinguisher, fuelId, flameActive, flameTempC, flameRadiusMm, isCoolFlame, showIsotherms, showVectors])

  // Mouse move handler for interactive sensor probe
  const handleMouseMove = (e) => {
    const canvas = canvasRef.current
    if (!canvas) return
    const rect = canvas.getBoundingClientRect()
    const x = e.clientX - rect.left
    const y = e.clientY - rect.top
    const centerX = canvas.width * 0.5
    const centerY = canvas.height * 0.52

    const dx = x - centerX
    const dy = y - centerY
    const dist = Math.sqrt(dx * dx + dy * dy)

    if (dist < 260) {
      // Calculate local temperature and CO2 estimate based on distance and draft
      const baseR = flameRadiusMm * 1.5 || 25
      const ratio = Math.max(0, 1 - dist / (baseR * 2.8))
      const localTemp = Math.round(22 + (flameTempC - 22) * (ratio ** 2))
      const localO2 = Math.max(2, (oxygen * (1 - ratio * 0.7)).toFixed(1))
      const localCO2 = Math.round(450 + (telemetry.co2Ppm - 450) * ratio)

      setHoverData({
        x: e.clientX,
        y: e.clientY,
        distMm: Math.round(dist * 0.4),
        temp: localTemp,
        o2: localO2,
        co2: localCO2,
      })
    } else {
      setHoverData(null)
    }
  }

  return (
    <div className="relative w-full h-[480px] lg:h-[580px] rounded-2xl overflow-hidden glass-panel border border-cyan-500/20 shadow-2xl flex flex-col group">
      {/* Top Chamber Header Bar */}
      <div className="absolute top-0 inset-x-0 z-20 flex items-center justify-between px-5 py-3.5 bg-gradient-to-b from-slate-950/90 via-slate-900/60 to-transparent backdrop-blur-md border-b border-cyan-500/10">
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2">
            <span className="relative flex h-3 w-3">
              <span className={`animate-ping absolute inline-flex h-full w-full rounded-full opacity-75 ${flameActive ? 'bg-cyan-400' : 'bg-slate-500'}`} />
              <span className={`relative inline-flex rounded-full h-3 w-3 ${flameActive ? (gravity < 0.05 ? 'bg-cyan-400 shadow-[0_0_8px_#38bdf8]' : 'bg-amber-400 shadow-[0_0_8px_#f59e0b]') : 'bg-slate-600'}`} />
            </span>
            <span className="text-xs font-mono font-bold tracking-wider text-cyan-300 uppercase">
              CIR RACK // {gravity < 0.05 ? '0G SPHERICAL DIFFUSION' : `BUOYANT ${gravity.toFixed(2)}G REGIME`}
            </span>
          </div>

          <span className="hidden sm:inline-block text-[11px] px-2 py-0.5 rounded font-mono bg-cyan-950/60 text-cyan-400 border border-cyan-800/40">
            {isCoolFlame ? 'COOL FLAME 460°C' : `${flameTempC}°C CORE`}
          </span>
        </div>

        {/* View toggles & quick triggers */}
        <div className="flex items-center gap-2">
          <button
            onClick={() => setShowIsotherms(!showIsotherms)}
            title="Alternar Isotermas Térmicas"
            className={`px-2.5 py-1 text-xs font-mono rounded flex items-center gap-1.5 transition-all ${
              showIsotherms 
                ? 'bg-cyan-500/20 text-cyan-300 border border-cyan-500/40 shadow-[0_0_10px_rgba(6,182,212,0.2)]' 
                : 'bg-slate-800/50 text-slate-400 border border-slate-700/50 hover:text-slate-200'
            }`}
          >
            <Layers className="w-3.5 h-3.5" />
            <span className="hidden md:inline">Isotermas</span>
          </button>

          <button
            onClick={() => setShowVectors(!showVectors)}
            title="Alternar Vectores de Convección"
            className={`px-2.5 py-1 text-xs font-mono rounded flex items-center gap-1.5 transition-all ${
              showVectors 
                ? 'bg-cyan-500/20 text-cyan-300 border border-cyan-500/40 shadow-[0_0_10px_rgba(6,182,212,0.2)]' 
                : 'bg-slate-800/50 text-slate-400 border border-slate-700/50 hover:text-slate-200'
            }`}
          >
            <Wind className="w-3.5 h-3.5" />
            <span className="hidden md:inline">Vectores</span>
          </button>

          {isIgnited ? (
            <button
              onClick={() => {
                sound.playClick()
                onTriggerExtinguish('co2')
              }}
              className="px-3 py-1 text-xs font-mono font-semibold rounded bg-red-500/20 text-red-300 border border-red-500/40 hover:bg-red-500/30 transition-all flex items-center gap-1.5 active:scale-95"
            >
              <ThermometerSnowflake className="w-3.5 h-3.5" />
              <span>Extinguir</span>
            </button>
          ) : (
            <button
              onClick={() => {
                sound.playIgnite()
                onIgnite()
              }}
              className="px-3 py-1 text-xs font-mono font-semibold rounded bg-amber-500/20 text-amber-300 border border-amber-500/50 hover:bg-amber-500/30 transition-all flex items-center gap-1.5 shadow-[0_0_15px_rgba(245,158,11,0.25)] active:scale-95 animate-pulse"
            >
              <Zap className="w-3.5 h-3.5" />
              <span>Ignición</span>
            </button>
          )}
        </div>
      </div>

      {/* Main Canvas Element */}
      <canvas 
        ref={canvasRef} 
        onMouseMove={handleMouseMove}
        onMouseLeave={() => setHoverData(null)}
        className="w-full h-full cursor-crosshair"
      />

      {/* Interactive Sensor HUD Tooltip on Hover */}
      {hoverData && (
        <div 
          className="absolute z-30 pointer-events-none p-3 rounded-lg glass-panel text-xs font-mono border border-cyan-400/40 shadow-xl"
          style={{ 
            left: `${hoverData.x - 70}px`, 
            top: `${hoverData.y - 120}px` 
          }}
        >
          <div className="flex items-center gap-2 text-cyan-300 font-bold border-b border-cyan-500/20 pb-1 mb-1.5">
            <Gauge className="w-3.5 h-3.5" />
            <span>SONDA CRIOMÉTRICA // {hoverData.distMm} mm</span>
          </div>
          <div className="grid grid-cols-2 gap-x-3 gap-y-0.5 text-slate-300">
            <span className="text-slate-400">Temp Local:</span>
            <span className={hoverData.temp > 800 ? 'text-amber-400 font-bold' : 'text-cyan-200'}>
              {hoverData.temp} °C
            </span>
            <span className="text-slate-400">O₂ Local:</span>
            <span>{hoverData.o2} %</span>
            <span className="text-slate-400">CO₂ Local:</span>
            <span>{hoverData.co2} ppm</span>
          </div>
        </div>
      )}

      {/* Bottom Telemetry Overlay Strip inside Canvas */}
      <div className="absolute bottom-3 inset-x-4 z-20 flex flex-wrap items-center justify-between gap-3 px-4 py-2.5 rounded-xl bg-slate-950/70 backdrop-blur-md border border-cyan-500/15 text-xs font-mono">
        <div className="flex items-center gap-4 flex-wrap">
          <div className="flex items-center gap-1.5 text-slate-300">
            <span className="text-slate-500">GRAVEDAD:</span>
            <span className={`font-bold ${gravity < 0.05 ? 'text-cyan-400' : 'text-amber-300'}`}>
              {gravity === 0 ? '0.00 g (Microgravedad)' : `${gravity.toFixed(2)} g`}
            </span>
          </div>
          <div className="flex items-center gap-1.5 text-slate-300">
            <span className="text-slate-500">O₂ CABINA:</span>
            <span className={`font-bold ${oxygen > 30 ? 'text-red-400 animate-pulse' : 'text-cyan-300'}`}>
              {oxygen}%
            </span>
          </div>
          <div className="flex items-center gap-1.5 text-slate-300">
            <span className="text-slate-500">VENTILACIÓN ECLSS:</span>
            <span className="font-bold text-slate-200">
              {airflow} cm/s {airflow > 0 ? '→' : '∅'}
            </span>
          </div>
          <div className="flex items-center gap-1.5 text-slate-300">
            <span className="text-slate-500">PRESIÓN:</span>
            <span className="font-bold text-slate-200">
              {pressure} kPa
            </span>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <span className="text-[11px] text-slate-400 hidden sm:inline">RÉGIMEN:</span>
          <span className={`px-2 py-0.5 rounded text-[11px] font-bold ${
            gravity < 0.05 
              ? 'bg-cyan-500/20 text-cyan-300 border border-cyan-500/30' 
              : 'bg-amber-500/20 text-amber-300 border border-amber-500/30'
          }`}>
            {gravity < 0.05 ? 'DIFUSIÓN ESFÉRICA (Gr ≈ 0)' : 'CONVECCIÓN BOYANTE (Boyance-Driven)'}
          </span>
        </div>
      </div>
    </div>
  )
}

/* ========================================================
   CANVAS DRAWING SUBROUTINES & PROCEDURAL PHYSICS
======================================================== */

function drawChamberHUD(ctx, width, height, cx, cy, t, params, showIsotherms, showVectors) {
  // Chamber crosshair and circular safety confinement boundary
  ctx.save()

  // Outer circular containment boundary (representing ISS CIR combustion chamber)
  const chamberRadius = Math.min(width, height) * 0.42
  ctx.beginPath()
  ctx.arc(cx, cy, chamberRadius, 0, Math.PI * 2)
  ctx.strokeStyle = 'rgba(56, 189, 248, 0.15)'
  ctx.lineWidth = 1.5
  ctx.setLineDash([4, 6])
  ctx.stroke()
  ctx.setLineDash([])

  // Concentric distance rings (10mm, 25mm, 50mm, 75mm)
  const rings = [45, 90, 140, 190]
  rings.forEach((r, idx) => {
    ctx.beginPath()
    ctx.arc(cx, cy, r, 0, Math.PI * 2)
    ctx.strokeStyle = 'rgba(56, 189, 248, 0.06)'
    ctx.lineWidth = 1
    ctx.stroke()

    // Ring label
    ctx.fillStyle = 'rgba(100, 116, 139, 0.4)'
    ctx.font = '9px JetBrains Mono'
    ctx.fillText(`${(idx + 1) * 20}mm`, cx + r + 4, cy - 3)
  })

  // Crosshair lines
  ctx.strokeStyle = 'rgba(56, 189, 248, 0.1)'
  ctx.beginPath()
  ctx.moveTo(cx - chamberRadius - 15, cy)
  ctx.lineTo(cx + chamberRadius + 15, cy)
  ctx.moveTo(cx, cy - chamberRadius - 15)
  ctx.lineTo(cx, cy + chamberRadius + 15)
  ctx.stroke()

  // Corner HUD Tech Accents
  drawHUDCorners(ctx, width, height)

  ctx.restore()
}

function drawHUDCorners(ctx, width, height) {
  const margin = 24
  const len = 16
  ctx.strokeStyle = 'rgba(56, 189, 248, 0.25)'
  ctx.lineWidth = 1.5

  // Top Left
  ctx.beginPath()
  ctx.moveTo(margin, margin + len)
  ctx.lineTo(margin, margin)
  ctx.lineTo(margin + len, margin)
  ctx.stroke()

  // Top Right
  ctx.beginPath()
  ctx.moveTo(width - margin - len, margin)
  ctx.lineTo(width - margin, margin)
  ctx.lineTo(width - margin, margin + len)
  ctx.stroke()

  // Bottom Left
  ctx.beginPath()
  ctx.moveTo(margin, height - margin - len)
  ctx.lineTo(margin, height - margin)
  ctx.lineTo(margin + len, height - margin)
  ctx.stroke()

  // Bottom Right
  ctx.beginPath()
  ctx.moveTo(width - margin - len, height - margin)
  ctx.lineTo(width - margin, height - margin)
  ctx.lineTo(width - margin, height - margin - len)
  ctx.stroke()
}

function drawFuelSource(ctx, cx, cy, fuelId, isIgnited) {
  ctx.save()

  if (fuelId === 'heptane_droplet') {
    // Silica quartz fiber / needle holding a liquid droplet
    ctx.strokeStyle = '#94a3b8'
    ctx.lineWidth = 1.2
    ctx.beginPath()
    ctx.moveTo(cx, cy - 40)
    ctx.lineTo(cx, cy - 4)
    ctx.stroke()

    // Droplet bead
    const grad = ctx.createRadialGradient(cx - 2, cy - 2, 1, cx, cy, 7)
    grad.addColorStop(0, '#ffffff')
    grad.addColorStop(0.4, 'rgba(56, 189, 248, 0.8)')
    grad.addColorStop(1, 'rgba(14, 165, 233, 0.3)')
    ctx.fillStyle = grad
    ctx.beginPath()
    ctx.arc(cx, cy, 6, 0, Math.PI * 2)
    ctx.fill()
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.6)'
    ctx.lineWidth = 1
    ctx.stroke()
  } else if (fuelId === 'pmma_solid') {
    // PMMA Polymer Rod / Slab
    ctx.fillStyle = 'rgba(203, 213, 225, 0.4)'
    ctx.strokeStyle = 'rgba(56, 189, 248, 0.6)'
    ctx.lineWidth = 1.5
    ctx.fillRect(cx - 8, cy - 2, 16, 28)
    ctx.strokeRect(cx - 8, cy - 2, 16, 28)

    // Pyrolyzing melt tip
    if (isIgnited) {
      ctx.fillStyle = 'rgba(251, 146, 60, 0.7)'
      ctx.beginPath()
      ctx.ellipse(cx, cy - 2, 9, 4, 0, 0, Math.PI * 2)
      ctx.fill()
    }
  } else if (fuelId === 'polyethylene_wire') {
    // Spacecraft Cable (Copper core with blue PE insulation)
    ctx.strokeStyle = '#38bdf8'
    ctx.lineWidth = 6
    ctx.beginPath()
    ctx.moveTo(cx - 30, cy + 12)
    ctx.lineTo(cx + 30, cy + 12)
    ctx.stroke()

    // Stripped copper core exposed
    ctx.strokeStyle = '#f59e0b'
    ctx.lineWidth = 2.5
    ctx.beginPath()
    ctx.moveTo(cx - 10, cy + 12)
    ctx.lineTo(cx + 10, cy + 12)
    ctx.stroke()
  } else if (fuelId === 'li_ion_battery') {
    // 18650 Battery Cell
    ctx.fillStyle = '#1e293b'
    ctx.strokeStyle = '#ef4444'
    ctx.lineWidth = 2
    ctx.fillRect(cx - 12, cy - 2, 24, 32)
    ctx.strokeRect(cx - 12, cy - 2, 24, 32)

    // Positive terminal cap
    ctx.fillStyle = '#cbd5e1'
    ctx.fillRect(cx - 5, cy - 6, 10, 4)

    // Warning hazard stripes
    ctx.fillStyle = '#ef4444'
    ctx.fillRect(cx - 10, cy + 8, 20, 4)
  } else {
    // Default burner orifice / needle
    ctx.fillStyle = '#475569'
    ctx.beginPath()
    ctx.arc(cx, cy, 5, 0, Math.PI * 2)
    ctx.fill()
  }

  ctx.restore()
}

function drawFlameAura(ctx, cx, cy, radius, buoyancy, draftX, t, telemetry, params) {
  ctx.save()
  ctx.globalCompositeOperation = 'screen'

  const { gravity, oxygen } = params
  const { isCoolFlame } = telemetry

  // Flame offset due to buoyancy (rises upwards) and draft (pushed right)
  const flameOffsetY = -buoyancy * 0.8
  const flameOffsetX = draftX

  // Flicker oscillation (in 0g: steady quiet sphere, in 1g: 10Hz convective flicker)
  const flicker = gravity < 0.05 
    ? Math.sin(t * 1.5) * 1.5 
    : Math.sin(t * 12) * (buoyancy * 0.22) + Math.cos(t * 22) * 3

  const r = Math.max(10, radius + flicker)

  // Gradient selection based on gravity and combustion regime:
  // In 0g: Chemiluminescent Blue Sphere (CH* & C2* emission at 430nm)
  // In 1g: Convective teardrop with Yellow incandescent soot tip
  const grad = ctx.createRadialGradient(
    cx + flameOffsetX * 0.5, 
    cy + flameOffsetY * 0.4, 
    r * 0.15, 
    cx + flameOffsetX * 0.5, 
    cy + flameOffsetY * 0.4, 
    r * (1 + (gravity > 0.4 ? 1.4 : 0.4))
  )

  if (isCoolFlame) {
    // NASA Cool Flame: faint diffuse blue-violet, low intensity
    grad.addColorStop(0, 'rgba(168, 85, 247, 0.4)')
    grad.addColorStop(0.4, 'rgba(56, 189, 248, 0.25)')
    grad.addColorStop(0.8, 'rgba(99, 102, 241, 0.1)')
    grad.addColorStop(1, 'rgba(0, 0, 0, 0)')
  } else if (gravity < 0.15) {
    // Microgravity pure diffusion flame: Gorgeous pure cyan/blue glowing ball
    const intensity = Math.min(1.0, 0.65 + (oxygen / 50))
    grad.addColorStop(0, `rgba(255, 255, 255, ${intensity * 0.95})`)
    grad.addColorStop(0.25, `rgba(56, 189, 248, ${intensity * 0.9})`)
    grad.addColorStop(0.6, `rgba(14, 165, 233, ${intensity * 0.55})`)
    grad.addColorStop(0.85, `rgba(37, 99, 235, ${intensity * 0.25})`)
    grad.addColorStop(1, 'rgba(2, 6, 23, 0)')
  } else {
    // Earth / Partial Gravity: Convective elongation with yellow/orange soot cap
    grad.addColorStop(0, 'rgba(255, 255, 255, 0.98)')
    grad.addColorStop(0.2, 'rgba(254, 240, 138, 0.95)')
    grad.addColorStop(0.45, 'rgba(249, 115, 22, 0.8)')
    grad.addColorStop(0.75, 'rgba(225, 29, 72, 0.45)')
    grad.addColorStop(1, 'rgba(2, 6, 23, 0)')
  }

  // Draw flame shell shape
  ctx.fillStyle = grad
  ctx.beginPath()

  if (gravity < 0.15 && Math.abs(draftX) < 4) {
    // Pure sphere in microgravity!
    ctx.arc(cx, cy, r, 0, Math.PI * 2)
  } else {
    // Teardrop / Elongated flame under gravity or draft
    const tipX = cx + flameOffsetX * 1.5
    const tipY = cy - r * (1 + buoyancy * 0.05) - (buoyancy * 1.2)
    const baseW = r * (1 - Math.min(0.5, gravity * 0.3))

    ctx.moveTo(cx - baseW, cy)
    ctx.bezierCurveTo(
      cx - baseW * 0.9, cy - r * 0.6,
      tipX - baseW * 0.4, tipY + r * 0.4,
      tipX, tipY
    )
    ctx.bezierCurveTo(
      tipX + baseW * 0.4, tipY + r * 0.4,
      cx + baseW * 0.9, cy - r * 0.6,
      cx + baseW, cy
    )
    ctx.bezierCurveTo(
      cx + baseW * 0.8, cy + r * 0.8,
      cx - baseW * 0.8, cy + r * 0.8,
      cx - baseW, cy
    )
  }
  ctx.fill()

  // Inner bright chemiluminescent core ring (NASA observation: spherical blue flame has thin bright reaction zone)
  if (gravity < 0.15) {
    ctx.beginPath()
    ctx.arc(cx, cy, r * 0.65, 0, Math.PI * 2)
    ctx.strokeStyle = 'rgba(125, 211, 252, 0.7)'
    ctx.lineWidth = 1.8
    ctx.stroke()
  }

  ctx.restore()
}

function spawnCombustionParticles(cx, cy, radius, buoyancy, draftX, params, telemetry, particlesRef, smokeRef, sparksRef) {
  const { gravity, oxygen, fuelId } = params
  const { isCoolFlame } = telemetry

  // In 0g, soot stays near the sphere or oxidizes slowly. In 1g, it shoots upward.
  const spawnRate = isCoolFlame ? 1 : Math.round(2 + (oxygen / 20) + (gravity * 3))

  for (let i = 0; i < spawnRate; i++) {
    // Angle around fuel
    const angle = gravity < 0.15 
      ? Math.random() * Math.PI * 2 
      : -Math.PI * 0.5 + (Math.random() - 0.5) * 1.4

    const speed = gravity < 0.15 ? 0.3 + Math.random() * 0.6 : 1.2 + gravity * 1.8

    // Velocity vector: isotropic in 0g, upward in 1g, plus draft
    const vx = Math.cos(angle) * speed + (draftX / 30)
    const vy = Math.sin(angle) * speed - (buoyancy * 0.04)

    particlesRef.current.push({
      x: cx + (Math.random() - 0.5) * 8,
      y: cy + (Math.random() - 0.5) * 8,
      vx,
      vy,
      size: gravity < 0.15 ? 2.5 + Math.random() * 3.5 : 2 + Math.random() * 2.5,
      life: 1.0,
      decay: gravity < 0.15 ? 0.012 : 0.024,
      isBlue: gravity < 0.25,
    })
  }

  // Battery thermal runaway or solid PMMA produces violent sparks and soot puffs
  if (fuelId === 'li_ion_battery' || oxygen > 35) {
    for (let j = 0; j < 3; j++) {
      const sparkAngle = (Math.random() - 0.5) * Math.PI * 2
      const sparkSpd = 3.5 + Math.random() * 5.0
      sparksRef.current.push({
        x: cx,
        y: cy,
        vx: Math.cos(sparkAngle) * sparkSpd + (draftX / 15),
        vy: Math.sin(sparkAngle) * sparkSpd - (buoyancy * 0.08),
        size: 1.5 + Math.random() * 2.0,
        life: 1.0,
        decay: 0.035,
      })
    }
  }

  // Limit particles count for 60fps performance
  if (particlesRef.current.length > 250) {
    particlesRef.current.splice(0, particlesRef.current.length - 250)
  }
  if (sparksRef.current.length > 100) {
    sparksRef.current.splice(0, sparksRef.current.length - 100)
  }
}

function drawCombustionParticles(ctx, particlesRef, smokeRef, sparksRef, draftX, buoyancy) {
  ctx.save()
  ctx.globalCompositeOperation = 'screen'

  // Update & Draw Flame Particles
  for (let i = particlesRef.current.length - 1; i >= 0; i--) {
    const p = particlesRef.current[i]
    p.x += p.vx
    p.y += p.vy
    p.life -= p.decay

    if (p.life <= 0) {
      particlesRef.current.splice(i, 1)
      continue
    }

    const alpha = p.life * 0.8
    ctx.beginPath()
    ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI * 2)

    if (p.isBlue) {
      ctx.fillStyle = `rgba(56, 189, 248, ${alpha})`
    } else {
      ctx.fillStyle = `rgba(249, 115, 22, ${alpha})`
    }
    ctx.fill()
  }

  // Update & Draw Sparks
  for (let i = sparksRef.current.length - 1; i >= 0; i--) {
    const s = sparksRef.current[i]
    s.x += s.vx
    s.y += s.vy
    s.life -= s.decay

    if (s.life <= 0) {
      sparksRef.current.splice(i, 1)
      continue
    }

    ctx.fillStyle = `rgba(254, 240, 138, ${s.life})`
    ctx.beginPath()
    ctx.arc(s.x, s.y, s.size, 0, Math.PI * 2)
    ctx.fill()
  }

  ctx.restore()
}

function drawIsotherms(ctx, cx, cy, baseRadius, buoyancy, draftX, temp, isCoolFlame) {
  ctx.save()
  ctx.setLineDash([3, 4])
  ctx.lineWidth = 1

  const contours = [
    { scale: 1.25, temp: Math.round(temp * 0.8), color: 'rgba(239, 68, 68, 0.45)' },
    { scale: 1.85, temp: Math.round(temp * 0.5), color: 'rgba(245, 158, 11, 0.35)' },
    { scale: 2.60, temp: Math.round(temp * 0.25), color: 'rgba(56, 189, 248, 0.25)' },
  ]

  contours.forEach(c => {
    const rx = baseRadius * c.scale
    const ry = (baseRadius + buoyancy * 0.4) * c.scale
    const offsetY = -buoyancy * 0.3 * (c.scale - 1)
    const offsetX = draftX * 0.4 * (c.scale - 1)

    ctx.strokeStyle = c.color
    ctx.beginPath()
    ctx.ellipse(cx + offsetX, cy + offsetY, rx, ry, 0, 0, Math.PI * 2)
    ctx.stroke()

    // Label on isotherm
    ctx.fillStyle = c.color
    ctx.font = '9px JetBrains Mono'
    ctx.fillText(`${c.temp}°C`, cx + rx + offsetX + 3, cy + offsetY)
  })

  ctx.restore()
}

function drawVelocityVectors(ctx, width, height, cx, cy, airflow, gravity, t) {
  ctx.save()
  ctx.strokeStyle = 'rgba(56, 189, 248, 0.12)'
  ctx.lineWidth = 1

  // Draw 6 subtle vector streamlines showing air drift
  const linesCount = 7
  for (let i = 0; i < linesCount; i++) {
    const yBase = cy - 120 + i * 40
    const offset = ((t * 40 + i * 60) % width) - (width * 0.5)

    const x = cx + offset
    const y = yBase - (gravity * 15 * Math.sin((x - cx) * 0.02))

    ctx.beginPath()
    ctx.moveTo(x - 14, y)
    ctx.lineTo(x + 14, y)
    ctx.stroke()

    // Arrowhead
    ctx.beginPath()
    ctx.moveTo(x + 10, y - 3)
    ctx.lineTo(x + 15, y)
    ctx.lineTo(x + 10, y + 3)
    ctx.stroke()
  }

  ctx.restore()
}

function drawSuppressionEffect(ctx, width, height, cx, cy, agent, t) {
  ctx.save()

  if (agent === 'co2' || agent === 'novec') {
    // Billowing gas blanket
    const grad = ctx.createRadialGradient(cx, cy, 10, cx, cy, 220)
    grad.addColorStop(0, 'rgba(255, 255, 255, 0.85)')
    grad.addColorStop(0.4, 'rgba(226, 232, 240, 0.6)')
    grad.addColorStop(0.8, 'rgba(148, 163, 184, 0.25)')
    grad.addColorStop(1, 'rgba(2, 6, 23, 0)')

    ctx.fillStyle = grad
    ctx.beginPath()
    ctx.arc(cx, cy, 220, 0, Math.PI * 2)
    ctx.fill()
  } else if (agent === 'mist') {
    // Fine water fog spray mist particles
    ctx.fillStyle = 'rgba(186, 230, 253, 0.7)'
    for (let i = 0; i < 60; i++) {
      const angle = Math.random() * Math.PI * 2
      const dist = Math.random() * 180
      ctx.beginPath()
      ctx.arc(cx + Math.cos(angle) * dist, cy + Math.sin(angle) * dist, 1.5, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  ctx.restore()
}

